from collections import deque

def compute_4dist_grid(grid):
    grid_h = len(grid)
    grid_w = len(grid[0])
    dist = [[float('inf')] * grid_w for _ in range(grid_h)]
    queue = deque()

    for r in range(grid_h):
        for c in range(grid_w):
            if grid[r][c] == 4:
                dist[r][c] = 0
                queue.append((r, c))

    dirs4 = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c = queue.popleft()
        d = dist[r][c]
        for dr, dc in dirs4:
            nr, nc = r + dr, c + dc
            if 0 <= nr < grid_h and 0 <= nc < grid_w:
                if dist[nr][nc] == float('inf') and grid[nr][nc] == 5:
                    dist[nr][nc] = d + 1
                    queue.append((nr, nc))

    return dist

