def transform(grid):
    def has_4_above(r, c, grid):
        for i in range(r):
            if grid[i][c] == 4:
                return True
        return False

    def has_4_below(r, c, grid):
        for i in range(r+1, len(grid)):
            if grid[i][c] == 4:
                return True
        return False

    def has_4_left(r, c, grid):
        for j in range(c):
            if grid[r][j] == 4:
                return True
        return False

    def has_4_right(r, c, grid):
        for j in range(c+1, len(grid[0])):
            if grid[r][j] == 4:
                return True
        return False

    out = []
    for r in range(len(grid)):
        row = []
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                ab = has_4_above(r, c, grid)
                bd = has_4_below(r, c, grid)
                lb = has_4_left(r, c, grid)
                rb = has_4_right(r, c, grid)

                # Become 3 if:
                # - has_4_above AND has_4_below
                # - has_4_above AND has_4_left AND has_4_right (and no below)
                # - has_4_below AND has_4_left AND has_4_right (and no above)
                # - has_4_left AND has_4_right (and neither above nor below)

                cond1 = ab and bd
                cond2 = not ab and bd and lb and rb
                cond3 = ab and not bd and lb and rb
                cond4 = not ab and not bd and lb and rb

                if cond1 or cond2 or cond3 or cond4:
                    row.append(3)
                else:
                    row.append(5)
            else:
                row.append(grid[r][c])
        out.append(row)
    return out

